mapper.select:
select sku.id,sku.sku_code,sku.sku_name,sku.product_id,sku.thumb_img,sku.sale_price,sku.market_price,sku.cost_price,sku.stock_num,sku.sale_num,sku.sku_spec,sku.weight,sku.volume,sku.status,sku.create_time,sku.update_time,sku.is_deleted from product_sku sku left join product p on p.id = sku.product_id
and ( sku.sku_name like CONCAT('%',#{keyword},'%') or p.name like CONCAT('%',#{keyword},'%') or p.brand_id in ( select id from brand where name like CONCAT('%',#{keyword},'%') ) )
and p.brand_id = #{brandId}
and p.category1_id = #{category1Id}
and p.category2_id = #{category2Id}
and p.category3_id = #{category3Id}
and p.status = 1 and p.audit_status = 1 and sku.is_deleted = 0 and p.is_deleted = 0
order by sku.sale_num desc
order by sku.sale_price asc
order by sku.sale_price desc

mapper.update:
update product_sku
set sale_num = sale_num + #{num}
where id = #{skuId}

update product_sku
set stock_num = stock_num - #{num}
where id = #{skuId}
and stock_num >= #{num}

